-- studio_lighting_setup.lua: GENERATED by rr-vfx-lighting (vfx.py build, 2026-09-28).
-- Paste into Studio's command bar once per place. It sets the Studio-level lighting options, lists effects
-- that would stack with the RRFX_ ones, and applies the default look for editing. It prints every old value.
local function hex(h) return Color3.fromHex(h) end
local function lvl(r, g, b) return Color3.fromRGB(r, g, b) end
local L = game:GetService("Lighting")
local function set(inst, prop, v)
	local ok, old = pcall(function() return inst[prop] end)
	local done = pcall(function() inst[prop] = v end)
	print(string.format("%s.%s: %s -> %s%s", inst.Name, prop, tostring(ok and old), tostring(v), done and "" or " (FAILED: not settable here)"))
end
set(L, "LightingStyle", Enum.LightingStyle.Realistic) -- tech.lighting.technology_api
set(L, "PrioritizeLightingQuality", true)
set(game:GetService("MaterialService"), "Use2022Materials", false) -- tech.lighting.materials_2022 (canon)
print("Lighting.Technology is deprecated and not scriptable (RBXD 2026-09-28): LightingStyle replaces it.")
for _, c in ipairs(L:GetChildren()) do
	if (c:IsA("PostEffect") or c:IsA("Atmosphere") or c:IsA("Sky")) and string.sub(c.Name, 1, 5) ~= "RRFX_" then
		print("existing effect (stacks with RR_Lighting; disable it if the look doubles up):", c:GetFullName(), c.ClassName)
	end
end
local function ensure(cls)
	if cls == "Lighting" then return L end
	local inst = L:FindFirstChild("RRFX_" .. cls)
	if not inst and cls == "Atmosphere" then inst = L:FindFirstChildOfClass("Atmosphere") end
	if not inst then inst = Instance.new(cls); inst.Name = "RRFX_" .. cls; inst.Parent = L end
	return inst
end
-- default look: grassland.day
