	set(i, "EnvironmentDiffuseScale", 0.35)
	set(i, "EnvironmentSpecularScale", 0.25)
	set(i, "ColorShift_Top", lvl(24, 22, 14))
	set(i, "ColorShift_Bottom", lvl(0, 6, 4))
